payment_reference']):'' ?></b></div><form method="post"><input type="hidden" name="_csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="rider_status"><input type="hidden" name="order_id" value="<?= (int)$o['id'] ?>"><input type="hidden" name="status" value="delivered"><button class="primary-button w-full">Confirm delivery complete <span>✓</span></button></form></article><?php endforeach; ?></div><?php endif; ?></section>

